/* ---------- Videos (Pexels, free licence) ---------- */
// Builds a list of fallback URLs for one Pexels clip: the player tries them in order.
function pexelsVideo(id, fps, w, h) {
  const base = `https://videos.pexels.com/video-files/${id}/${id}-`;
  if (w === 4096) {
    return [`${base}hd_2048_1080_${fps}fps.mp4`, `${base}hd_1920_1080_${fps}fps.mp4`, `${base}uhd_${w}_${h}_${fps}fps.mp4`];
  }
  return [`${base}hd_1920_1080_${fps}fps.mp4`, `${base}uhd_${w}_${h}_${fps}fps.mp4`];
}

